Definition fh_join_stmt : Prop :=
  forall rax ra sp gp tp t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 s0v s1v s2v s3v s4v s4x s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m m1 : mem) (P E lo shi : Z) (c1 : pcore) (pad7 pad2 ej j8 j24 : list byte) (g : bool) (st' : Z),
  fh_ctx m m1 sp s0v s1v s2v s3v s4v ra P E lo shi c1 pad7 pad2 ej j8 j24 g ->
  st_pure FH_STACK sp P E lo shi ->
  0 <= st' < 2^31 ->
  evt asegs (fh_post_r (EC_clear, pc_set_state c1 st') g ra sp gp tp s0v s1v s2v s3v s4v s5 s6 s7 s8 s9 s10 s11 F fc P E lo shi pad7 pad2 m)
    (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -80)) gp tp t0 t1 t2 (wz E) (wz P) (wz st') a1 a2 a3 a4 a5 a6 a7
              (wz (P + 72)) (wz 2147450880) s4x s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 0xce600) fc None m1 (seg_rom asegs)).

